"""Parser robustness on deliberately messy resumes (generated by scripts/generate_messy_samples.py)."""
import datetime as dt
import json
from pathlib import Path

import pytest

from app.parsing import extract_text, parse_resume

DIR = Path(__file__).resolve().parents[2] / "sample_resumes_messy"
EXPECTED = json.loads((DIR / "expected.json").read_text())


def expected_years(spans):
    t = dt.date.today(); now = t.year * 12 + t.month
    iv = sorted((y1 * 12 + m1, now if y2 is None else y2 * 12 + (m2 or 1)) for y1, m1, y2, m2 in spans)
    total, cs, ce = 0, None, None
    for a, b in iv:
        if ce is None or a > ce:
            total += (ce - cs) if ce is not None else 0; cs, ce = a, b
        else:
            ce = max(ce, b)
    return round((total + ce - cs) / 12, 1)


@pytest.mark.parametrize("fname", sorted(EXPECTED))
def test_messy_resume(fname):
    exp = EXPECTED[fname]
    r = parse_resume(extract_text(fname, (DIR / fname).read_bytes()), fname)
    assert r["name"] == exp["name"], f"name: {r['name']}"
    want = exp.get("stated") or expected_years(exp["spans"])
    assert abs(r["years"] - want) <= 0.2, f"years {r['years']} vs expected {want}"
    for s in exp["skills"]:
        assert s in r["skills"], f"missing skill {s}"
    assert r["education_level"] == exp["edu"]
